/**
 * Direct PostgreSQL connection for authentication queries
 * 
 * This is a temporary workaround for Prisma P1010 bug with PostgreSQL 15+
 * See: https://github.com/prisma/prisma/issues/16386
 * 
 * Once Prisma fixes the introspection issue, we can remove this and use Prisma Client directly.
 * 
 * This uses the same connection string as Prisma and provides the same functionality
 * but bypasses Prisma's introspection engine that's causing the permission errors.
 */

import { Pool } from 'pg';

// Parse DATABASE_URL and ensure proper format for pg library
const getConnectionConfig = () => {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error('DATABASE_URL environment variable is not set');
  }
  
  // Parse the connection string properly
  // Remove schema parameter for pg library (it's not needed)
  let cleanUrl = url.replace(/\?schema=.*$/, '');
  
  // Parse URL to extract components - use explicit parameters for reliability
  try {
    const urlObj = new URL(cleanUrl);
    
    // Use the hostname as-is from the connection string
    // Note: If you have a local PostgreSQL on port 5432, it may conflict with Docker
    // Ensure Docker container is accessible or use a different port mapping
    const host = urlObj.hostname;
    
    // Add connection timeout and retry logic for reliability
    const connectionConfig: any = {
      host,
      port: parseInt(urlObj.port || '5432', 10),
      database: urlObj.pathname.slice(1),
      user: urlObj.username,
      password: urlObj.password,
      max: 20,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 5000,
    };
    
    // Add SSL configuration if needed (set to false for local Docker)
    if (host === 'localhost' || host === '127.0.0.1') {
      connectionConfig.ssl = false;
    }
    
    if (!connectionConfig.user || !connectionConfig.database) {
      throw new Error('Invalid DATABASE_URL: missing user or database');
    }
    
    return connectionConfig;
  } catch (error) {
    console.error('Error parsing DATABASE_URL:', error);
    throw new Error(`Invalid DATABASE_URL format: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
};

const pool = new Pool(getConnectionConfig());

export interface UserWithCredentials {
  id: string;
  email: string;
  name: string | null;
  image: string | null;
  passwordHash: string;
}

/**
 * Get user by email with credentials
 * This replaces db.user.findUnique() until Prisma P1010 is fixed
 */
export async function getUserByEmailWithCredentials(
  email: string
): Promise<UserWithCredentials | null> {
  const client = await pool.connect();
  try {
    const result = await client.query<UserWithCredentials>(
      `SELECT 
        u.id::text as id,
        u.email,
        u.name,
        u.image,
        uc."passwordHash"::text as "passwordHash"
      FROM users u
      INNER JOIN user_credentials uc ON u.id = uc."userId"
      WHERE u.email = $1
      LIMIT 1`,
      [email]
    );

    if (result.rows.length === 0) {
      return null;
    }

    return result.rows[0];
  } finally {
    client.release();
  }
}

/**
 * Get all users
 * This replaces db.user.findMany() until Prisma P1010 is fixed
 */
export async function getAllUsers(): Promise<Array<{
  id: string;
  email: string;
  name: string | null;
  emailVerified: Date | null;
  createdAt: Date;
  updatedAt: Date;
}>> {
  const client = await pool.connect();
  try {
    const result = await client.query<{
      id: string;
      email: string;
      name: string | null;
      emailVerified: Date | null;
      createdAt: Date;
      updatedAt: Date;
    }>(
      `SELECT 
        u.id::text as id,
        u.email,
        u.name,
        u."emailVerified",
        u."createdAt",
        u."updatedAt"
      FROM users u
      ORDER BY u."createdAt" DESC`
    );

    return result.rows;
  } finally {
    client.release();
  }
}

/**
 * Get user by ID
 */
export async function getUserById(id: string): Promise<{
  id: string;
  email: string;
  name: string | null;
  emailVerified: Date | null;
  createdAt: Date;
  updatedAt: Date;
} | null> {
  const client = await pool.connect();
  try {
    const result = await client.query<{
      id: string;
      email: string;
      name: string | null;
      emailVerified: Date | null;
      createdAt: Date;
      updatedAt: Date;
    }>(
      `SELECT 
        u.id::text as id,
        u.email,
        u.name,
        u."emailVerified",
        u."createdAt",
        u."updatedAt"
      FROM users u
      WHERE u.id = $1
      LIMIT 1`,
      [id]
    );

    if (result.rows.length === 0) {
      return null;
    }

    return result.rows[0];
  } finally {
    client.release();
  }
}

/**
 * Check if user exists by email
 */
export async function userExistsByEmail(email: string): Promise<boolean> {
  const client = await pool.connect();
  try {
    const result = await client.query(
      `SELECT 1 FROM users WHERE email = $1 LIMIT 1`,
      [email]
    );
    return result.rows.length > 0;
  } finally {
    client.release();
  }
}

/**
 * Create user with credentials
 */
export async function createUserWithCredentials(
  email: string,
  passwordHash: string,
  name?: string
): Promise<{
  id: string;
  email: string;
  name: string | null;
  emailVerified: Date | null;
  createdAt: Date;
  updatedAt: Date;
}> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    
    // Create user
    const userResult = await client.query<{ id: string }>(
      `INSERT INTO users (id, email, name, "createdAt", "updatedAt")
       VALUES (gen_random_uuid()::text, $1, $2, NOW(), NOW())
       RETURNING id::text as id`,
      [email, name || null]
    );

    const userId = userResult.rows[0].id;

    // Create credentials
    await client.query(
      `INSERT INTO user_credentials (id, "userId", "passwordHash", "createdAt", "updatedAt")
       VALUES (gen_random_uuid()::text, $1, $2, NOW(), NOW())`,
      [userId, passwordHash]
    );

    await client.query('COMMIT');

    // Fetch the created user
    const user = await getUserById(userId);
    if (!user) {
      throw new Error('Failed to retrieve created user');
    }

    return user;
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }
}

/**
 * Update user
 */
export async function updateUser(
  id: string,
  updates: { name?: string }
): Promise<{
  id: string;
  email: string;
  name: string | null;
  emailVerified: Date | null;
  createdAt: Date;
  updatedAt: Date;
} | null> {
  const client = await pool.connect();
  try {
    const setClauses: string[] = [];
    const values: any[] = [];
    let paramIndex = 1;

    if (updates.name !== undefined) {
      setClauses.push(`name = $${paramIndex++}`);
      values.push(updates.name);
    }

    if (setClauses.length === 0) {
      return getUserById(id);
    }

    setClauses.push(`"updatedAt" = NOW()`);
    values.push(id);

    await client.query(
      `UPDATE users 
       SET ${setClauses.join(', ')}
       WHERE id = $${paramIndex}`,
      values
    );

    return getUserById(id);
  } finally {
    client.release();
  }
}

/**
 * Delete user
 */
export async function deleteUser(id: string): Promise<boolean> {
  const client = await pool.connect();
  try {
    const result = await client.query(
      `DELETE FROM users WHERE id = $1`,
      [id]
    );
    return (result.rowCount ?? 0) > 0;
  } finally {
    client.release();
  }
}

// Graceful shutdown
process.on('beforeExit', async () => {
  await pool.end();
});
